body{font-family:Arial,Helvetica,sans-serif;color:#182641;background:#fff}#abe-preview{max-width:1320px;margin:auto}.amp-site-header{background:#fff;border-bottom:1px solid #dce4f0;padding:18px 22px}.amp-site-header .head-contact{margin:0;padding:8px 0;list-style:none}.amp-site-header .head-contact a{color:#142d82;text-decoration:none}.nav-bar{background:#142d82}.menu-btn{background:#142d82;color:#fff;border:0;padding:12px 20px}.banner{background:#e5efff;color:#142d82;padding:30px 20px}.banner-text{color:#142d82;font-family:Georgia,serif}.search-form input{border:1px solid #dce4f0;border-radius:4px}.search-form button{background:#142d82;color:white;border:0}.amp-site-footer{background:linear-gradient(125deg,#101f66,#184fd4);color:#fff;padding:35px 24px;margin-top:40px}.amp-site-footer a,.amp-site-footer p,.amp-site-footer .footer-title{color:#fff}.amp-site-footer .footer-contact-background{background:transparent;border-bottom:1px solid #ffffff40;margin-bottom:24px;padding-bottom:16px}.amp-site-footer .footer-contact-no{font-size:14px}.copyright{background:#101f66;color:#fff;padding:15px;text-align:center}h1,h2,h3{color:#142d82}.rport-title a{color:#142d82}.footer-list{line-height:1.9}@media(max-width:600px){.amp-site-header{padding:12px}.amp-site-header .col-3,.amp-site-header .col-9{width:100%;text-align:center}.amp-site-header .head-contact{font-size:12px}.amp-site-footer>.row>.col-4{width:100%;float:none;text-align:left;margin-bottom:22px}.amp-site-footer .footer-contact-no{font-size:11px}}
